const r = $input.first().json;
return [{
  json: {
    ok: r.ok,
    returncode: r.returncode,
    command: r.cmd,
    claim_boundary: r.claim_boundary,
    stdout_preview: r.stdout,
    stderr_preview: r.stderr,
    generated_at: new Date().toISOString()
  }
}];

const r = $input.first().json;
const text = String(r.stdout_preview || '') + '\n' + String(r.claim_boundary || '');
const forbidden = [
  '240-run six-variant',
  'production O-RAN deployment readiness',
  'packet-capture network-impairment benchmark',
  'public-chain benchmark',
  'full media-plane QoE validation'
];
const hits = forbidden.filter(x => text.toLowerCase().includes(x.toLowerCase()));
return [{
  json: {
    ...r,
    claim_boundary_review_passed: hits.length === 0,
    forbidden_phrase_hits: hits,
    reviewer_note: hits.length === 0
      ? 'Claim-boundary review passed for the generated Stage E/F summary.'
      : 'Claim-boundary review detected unsupported language. Inspect before using in the paper.'
  }
}];
